INSERT INTO posts (id,user_id,type,body,created_at) VALUES (1,1,'funding','Alpha Startup is opening a $1.5M seed round. 12 clinics live, 40k patient visits, and an 18% MoM growth rate. Looking for health-focused investors who understand last-mile care. Our deck is on my profile for verified investors.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 10800000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (1,5,'Impressive traction on clinic activation. Would love to see your retention data — sending a message.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 9000000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (1,10,'Happy to help with your seed narrative. The offline-first angle is your strongest story.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 7920000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (1,9,'Strong team and a clear wedge. Happy to help with your technical diligence story.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 6840000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (2,5,'call','Alpha Demo Fund is actively looking for pre-seed and seed founders in HealthTech and Fintech across South Asia and Africa. Cheque size $250K–$1.5M. Share a short pitch with traction numbers and we will respond within a week.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 25200000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (2,3,'Is cross-border payments infrastructure in scope?',((CAST(strftime('%s','now') AS INTEGER)*1000) - 23400000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (2,5,'Absolutely — especially if you have real volume. Send a pitch via Alignment.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 22320000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (2,1,'Thanks Alpha Investor — sending a pitch your way shortly.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 21240000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (3,10,'insight','Three questions I ask every founder before their first fundraise: 1) What do you know about your customers that investors do not? 2) What milestone will this round fund? 3) What happens if you raise half? Clear answers beat polished slides.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 39600000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (3,2,'Number 3 is a great forcing function. Working on it now.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 37800000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (3,1,'Great list. Saving this for our seed prep.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 36720000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (4,2,'update','Bravo Startup just finished pilot #3: our sensors flagged a failing transformer 11 days before it would have caused an outage. We are now in talks with two regional utilities. Huge thanks to everyone who introduced us.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 72000000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (4,7,'That is a strong proof point. Let us talk — Meridian is looking at grid tech.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 70200000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (5,3,'funding','Charlie Startup is raising a $2M seed to expand settlement corridors from West Africa to East Africa. We process $1.2M a month for 600 SMEs. Looking for fintech investors with African market experience.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 93600000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (5,5,'Charlie Startup looks interesting — let us talk about corridors and unit economics.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 91800000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (5,11,'Happy to review your FX and settlement cost model before you raise.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 90720000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (6,11,'insight','Cap table hygiene tip: model your next two rounds BEFORE you sign a SAFE. Founders are often surprised how much dilution stacks up across notes. A 20-minute spreadsheet exercise saves months of regret.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 108000000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (6,4,'Is there a template you recommend?',((CAST(strftime('%s','now') AS INTEGER)*1000) - 106200000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (6,11,'Yes — see the Learning Hub for a simple dilution model outline.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 105120000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (6,1,'Bookmarked. This is exactly what we are modelling this month.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 104040000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (7,7,'call','Bravo Demo Ventures is reviewing seed and Series A deals in grid technology, battery materials and industrial automation. If you are building hardware with software leverage, we would like to hear from you.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 144000000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (8,4,'update','Delta Startup reached 1,800 teachers on the waitlist this week — all organic, from teacher WhatsApp groups. Now looking for a mentor in marketing and community building.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 172800000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (8,10,'Community-led growth is a great fit for your audience. Book a slot with me in the Mentor’s Room.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 171000000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (8,9,'Congratulations — organic traction like that is a strong signal.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 169920000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (9,9,'learning','Prototype to product-market fit checklist: weekly user interviews, one core metric, a retention curve that flattens, and a paying customer who would be upset if you disappeared. If you cannot tick three of four, keep building.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 198000000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (10,12,'update','Just wrapped a two-day operations workshop with four early-stage teams. The most common gap: no weekly operating rhythm. A simple Monday priorities / Friday review loop changed everything for them.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 252000000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (11,8,'call','Charlie Demo Angels is opening a new syndicate round for early-stage fintech and agri-tech founders. Cheques from $50K. Verified founders welcome to pitch through INverge.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 288000000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (12,1,'update','Milestone: Alpha Startup crossed 40,000 patient visits assisted. A nurse in a clinic with no internet told us the offline mode saved her an hour a day. That is why we build.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 360000000));
INSERT INTO comments (post_id,user_id,body,created_at) VALUES (12,9,'Offline-first is genuinely hard. Well done to the whole team.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 358200000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (13,5,'learning','What I look for in a first meeting: a founder who can explain the problem in one sentence, name three real customers, and tell me what they would do with the money in 18 months.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 432000000));
INSERT INTO posts (id,user_id,type,body,created_at) VALUES (14,10,'learning','New in the Learning Hub: a guide to your first 100 customers. Spoiler — it is mostly conversations, not campaigns.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 504000000));
