INSERT INTO questions (id,user_id,title,body,tag,created_at) VALUES (1,4,'How do I find my first 100 users with almost no budget?','We are a pre-seed edtech tool for teachers. Paid ads feel wasteful. What has worked for you?','Marketing',((CAST(strftime('%s','now') AS INTEGER)*1000) - 108000000));
INSERT INTO answers (question_id,user_id,body,created_at) VALUES (1,10,'Go where your users already talk. For teachers that is WhatsApp and Telegram groups, local teacher communities and school WhatsApp parents groups. Offer to build one free resource for the group, then ask for feedback — not signups. Track which conversations turn into repeat usage and double down on that channel only.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 100800000));
INSERT INTO answers (question_id,user_id,body,created_at) VALUES (1,9,'Also record every user interview. Your first 100 users are your best source of product insight, not just distribution.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 97200000));
INSERT INTO questions (id,user_id,title,body,tag,created_at) VALUES (2,2,'When is the right time to start talking to seed investors?','We have 3 pilots and no revenue yet. Are we too early?','Fundraising',((CAST(strftime('%s','now') AS INTEGER)*1000) - 187200000));
INSERT INTO answers (question_id,user_id,body,created_at) VALUES (2,11,'Start relationships 3–6 months before you need the money. Share short updates monthly. Formally raise when you can show a repeatable pattern: pilots converting to paid contracts is that pattern for hardware. Pilots alone, without a path to revenue, usually read as pre-seed.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 180000000));
INSERT INTO questions (id,user_id,title,body,tag,created_at) VALUES (3,3,'How should we think about SAFE vs priced round at seed?','We are raising $2M. Investors are split on instruments.','Finance',((CAST(strftime('%s','now') AS INTEGER)*1000) - 324000000));
INSERT INTO answers (question_id,user_id,body,created_at) VALUES (3,11,'SAFEs are faster and cheaper, but they defer the valuation conversation and can stack dilution. A priced round gives clarity and governance but costs more in legal time. Above ~$1.5M many institutional investors prefer priced. Model both scenarios on your cap table and talk to a startup lawyer before choosing.',((CAST(strftime('%s','now') AS INTEGER)*1000) - 316800000));
INSERT INTO questions (id,user_id,title,body,tag,created_at) VALUES (4,1,'How do you structure the first technical hires after seed?','We are a team of 4 and plan to hire 6 over 12 months.','Talent / HR',((CAST(strftime('%s','now') AS INTEGER)*1000) - 396000000));
