INSERT INTO resources (type,title,summary,body,url,author_id,author_name,tags,created_at) VALUES ('community','Dilution model outline for a SAFE round','A simple spreadsheet outline to model how SAFEs convert at your priced round.','Columns: investor, amount, valuation cap, discount, conversion price, shares issued. Add rows per SAFE, then model the priced round to see post-money ownership for founders, pool and investors. Re-run with 2–3 scenarios before you sign anything.',NULL,11,'Charlie Mentor','Finance,Fundraising',((CAST(strftime('%s','now') AS INTEGER)*1000) - 216000000));
